"use strict";(self.webpackChunkdg_knowlege_base=self.webpackChunkdg_knowlege_base||[]).push([[7761],{4355:e=>{e.exports=JSON.parse('{"tag":{"label":"Dashboards","permalink":"/datagol-knowlegde-base-v1/docs/tags/dashboards","allTagsPath":"/datagol-knowlegde-base-v1/docs/tags","count":33,"items":[{"id":"BI and Visualizer/Dashboard/About dashboard","title":"About dashboard","description":"Dashboards are central to visualizing your data, as they hold all your created widgets. A dashboard displays information from various sources on a single screen, using visuals like charts and graphs for easy monitoring and quick analysis. Dashboards can be embedded for third-party viewing, providing access to live data.","permalink":"/datagol-knowlegde-base-v1/docs/BI and Visualizer/Dashboard/about-dashboard"},{"id":"BI and Visualizer/Filters/About filters","title":"About filters","description":"Filters are essential components in Business Intelligence (BI) analytics, both within individual widgets and across entire dashboards. They allow users to narrow down large datasets and focus on specific, relevant information, making data analysis more efficient and insights clearer.  Filters are applied at different levels to control the scope of data displayed. In DataGOL, the following types of filters can be applied for a visualization:","permalink":"/datagol-knowlegde-base-v1/docs/BI and Visualizer/Filters/about-filters"},{"id":"BI and Visualizer/About Visualizer","title":"About Visualizer","description":"The Visualizer is a crucial component for performing Business Intelligence (BI) Analytics. It\'s where you actively engage in data visualization to transform raw data into actionable insights, ultimately driving data-driven decision-making.","permalink":"/datagol-knowlegde-base-v1/docs/BI and Visualizer/about-visualizer"},{"id":"BI and Visualizer/Dashboard/External dashboards/Accessing external dashboards","title":"Accessing external dashboards","description":"To access external dashboards, do the following:","permalink":"/datagol-knowlegde-base-v1/docs/BI and Visualizer/Dashboard/External dashboards/accessing-external-dashboards"},{"id":"BI and Visualizer/Filters/Accessing saved set of filters","title":"Accessing saved set of filters","description":"1.  From a workspace, access a dashboard.","permalink":"/datagol-knowlegde-base-v1/docs/BI and Visualizer/Filters/accessing-the-saved-set-of-page-level-or-dashboard-level-filters"},{"id":"BI and Visualizer/Filters/Adding page or dashboard filters","title":"Adding page or dashboard filters","description":"Do the following to add page level or dashboard level filters:","permalink":"/datagol-knowlegde-base-v1/docs/BI and Visualizer/Filters/adding-page-level-or-dashboard-level-filters"},{"id":"BI and Visualizer/Filters/Adding widget filters","title":"Adding widget filters","description":"You can add a widget filter while creating a widget as well as directly from a dashboard.","permalink":"/datagol-knowlegde-base-v1/docs/BI and Visualizer/Filters/adding-widget-level-filters"},{"id":"BI and Visualizer/Aggregate functions","title":"Aggregate functions","description":"Aggregate functions are calculations performed on a set of values to produce a single summary value. They are incredibly useful for gaining insights from large datasets by condensing information into meaningful metrics. In effect you are prompting the Visualizer to take a numerical column, perform a specific calculation (Sum, Max, Min, Average, Count, Unique Count etc.) on its values, and then display the results grouped by the categories in this other column.","permalink":"/datagol-knowlegde-base-v1/docs/BI and Visualizer/aggregate-functions"},{"id":"BI and Visualizer/Widgets/BI Widgets - capabilities and combinations","title":"BI Widgets - capabilities and combinations","description":"This guide outlines the data visualization possibilities within our BI tool. Understand how to combine your data columns with different widgets to uncover insights. This guide will help a business user understand what visualizations they can expect to be suggested and how their data (Dimensions, Metrics, Date Times) will generally be used if they pick that suggestion.","permalink":"/datagol-knowlegde-base-v1/docs/BI and Visualizer/Widgets/bi-widgets-capabilities-combinations"},{"id":"Workbooks/Conditional formatting for tables","title":"Conditional formatting for tables","description":"Enhance your data analysis with the new conditional formatting feature for tables and pivot tables. You can now define custom rules and dynamically color-code cells based on their values, allowing for quick visual identification of key data points that meet specific thresholds or criteria.","permalink":"/datagol-knowlegde-base-v1/docs/Workbooks/conditional-format"},{"id":"BI and Visualizer/Widgets/Configuring and setting widgets","title":"Configuring and setting widgets","description":"DataGOL offers a flexible way to visualize your data through configurable widgets. When you configure a widget, you\'re essentially defining what data is displayed and how it\'s presented visually. This involves selecting the specific columns for the x and y axis, deciding if the y-axis should display cumulative values, and choosing from a range of technical indicators to overlay. You also fine-tune the aesthetic details like numeric notations and chart label colors during configuration.","permalink":"/datagol-knowlegde-base-v1/docs/BI and Visualizer/Widgets/configuring-setting-widgets"},{"id":"BI and Visualizer/Widgets/Create a visualization or widget","title":"Create a visualization or widget","description":"1.  On the Home page, from the left navigation panel, click Workspace and  from the list of workspaces, select a workspace from where you want to visualize data.","permalink":"/datagol-knowlegde-base-v1/docs/BI and Visualizer/Widgets/create-visualization-or-create-widget"},{"id":"BI and Visualizer/Dashboard/Creating dashboards","title":"Creating dashboards","description":"To create a dashboard, do the following:","permalink":"/datagol-knowlegde-base-v1/docs/BI and Visualizer/Dashboard/creating-dashboard"},{"id":"BI and Visualizer/Dashboard/External dashboards/Creating external dashboards","title":"Creating external dashboards","description":"The External Dashboard provides a centralized location for accessing critical dashboards from across the platform and a space for users who need a high-level overview of key metrics.","permalink":"/datagol-knowlegde-base-v1/docs/BI and Visualizer/Dashboard/External dashboards/creating-external-dashboards"},{"id":"BI and Visualizer/Dashboard/Creating widgets from dashboards","title":"Creating widgets from dashboards","description":"1.  From a workspace, access a dashboard.","permalink":"/datagol-knowlegde-base-v1/docs/BI and Visualizer/Dashboard/creating-widgets-from-dashboards"},{"id":"BI and Visualizer/Filters/Dependent filters","title":"Dependent filters","description":"By default, page-level filters operate with a dependency hierarchy. Consider a scenario with \\"Country,\\" \\"State,\\" and \\"City\\" filters. With this dependency structure, upon selecting a specific country in the first filter, the subsequent \\"State\\" filter will dynamically display only the states within that chosen country.","permalink":"/datagol-knowlegde-base-v1/docs/BI and Visualizer/Filters/dependent-filters"},{"id":"BI and Visualizer/Drill Down","title":"Drill Down","description":"The following types of drill-down are included in DataGOL:","permalink":"/datagol-knowlegde-base-v1/docs/BI and Visualizer/drill-down-column-drill-down-widget-drill-down"},{"id":"BI and Visualizer/Filters/Editing page filters","title":"Editing page filters","description":"To edit page level filters, do the following:","permalink":"/datagol-knowlegde-base-v1/docs/BI and Visualizer/Filters/editing-page-level-filters"},{"id":"BI and Visualizer/Dashboard/Embedding analytics for third party views","title":"Embedding analytics for third party views","description":"Do the following to embed analytics for third party views:","permalink":"/datagol-knowlegde-base-v1/docs/BI and Visualizer/Dashboard/embedding-analytics-third-party-views"},{"id":"BI and Visualizer/Filters/Excluding or including filters","title":"Excluding or including filters","description":"You have granular control over how filters interact with your dashboard widgets. Specifically, you can choose to exclude certain widgets entirely from a filter\'s operation. Conversely, you also have the option to selectively include only specific widgets for a filter, ensuring the filter affects only the data visualizations you intend. This flexibility allows for precise and targeted data analysis within your dashboard.","permalink":"/datagol-knowlegde-base-v1/docs/BI and Visualizer/Filters/excluding-or-including-filters"},{"id":"BI and Visualizer/Formulas and parameters","title":"Formulas and parameters","description":"Creating formulas","permalink":"/datagol-knowlegde-base-v1/docs/BI and Visualizer/creating-formulas-and-parameters-in-visualizer"},{"id":"BI and Visualizer/Dashboard/Linking dashboards","title":"Linking dashboards","description":"You can link the dashboard reports you want to view from within a widget.","permalink":"/datagol-knowlegde-base-v1/docs/BI and Visualizer/Dashboard/linking dashboards"},{"id":"BI and Visualizer/Dashboard/Managing layout and widgets in dashboards","title":"Managing layout and widgets in dashboards","description":"You can change the layout of your dashboards by changing the order of the widgets in the Dashboard.","permalink":"/datagol-knowlegde-base-v1/docs/BI and Visualizer/Dashboard/managing-layout-widgets-in-dashboards"},{"id":"BI and Visualizer/Filters/Reordering page level filters","title":"Reordering page level filters","description":"From the Manager Filters section, you can rearrange the filters. Based upon on the rearrangement the hierarchy of the dependent filters changes","permalink":"/datagol-knowlegde-base-v1/docs/BI and Visualizer/Filters/reorder-page-level-filters"},{"id":"BI and Visualizer/Widgets/Saving a widget to dashboard","title":"Saving a widget to dashboard","description":"After you create a widget, ensure to save the widget to a dashboard.","permalink":"/datagol-knowlegde-base-v1/docs/BI and Visualizer/Widgets/saving-a-widget-to-dashboard"},{"id":"BI and Visualizer/Filters/Saving filters","title":"Saving filters","description":"Within the dashboard interface, you possess the ability to define specific views suited to your analytical needs by applying filters. These customized filter configurations can be persistently stored for your convenience, allowing for their subsequent and immediate retrieval and application. This feature empowers you to create and save preferred data perspectives, ensuring efficient access to the insights most relevant to your work instantly.","permalink":"/datagol-knowlegde-base-v1/docs/BI and Visualizer/Filters/saving-set-of-page-level-or-dashboard-level-filters"},{"id":"BI and Visualizer/Dashboard/External dashboards/Sharing external dashboards","title":"Sharing external dashboards","description":"To share the external dashboards, do the following:","permalink":"/datagol-knowlegde-base-v1/docs/BI and Visualizer/Dashboard/External dashboards/sharing-external-dashboards"},{"id":"BI and Visualizer/Filters/Show or hide widget filters","title":"Show or hide widget filters","description":"To show or hide the widget level filters, do the following:","permalink":"/datagol-knowlegde-base-v1/docs/BI and Visualizer/Filters/show-or-hide-widget-level-filters"},{"id":"BI and Visualizer/Dashboard/Switching workbooks in a dashboard","title":"Switching workbooks in a dashboard","description":"You can change the underlying data source of a dashboard from one workbook to another.","permalink":"/datagol-knowlegde-base-v1/docs/BI and Visualizer/Dashboard/switching-workbooks-in-a-dashboard"},{"id":"BI and Visualizer/Widgets/Understanding widget Icons","title":"Understanding widget Icons","description":"On the right side of the generated widgets, in a panel, the followings icons are listed while configuring or setting a widget.","permalink":"/datagol-knowlegde-base-v1/docs/BI and Visualizer/Widgets/understanding-widget-icons"},{"id":"BI and Visualizer/Widgets/Viewing SQL query in a widget","title":"Viewing SQL query in a widget","description":"To view SQL query in a widget, do the following:","permalink":"/datagol-knowlegde-base-v1/docs/BI and Visualizer/Widgets/viewing-sql-query-in-a-widget"},{"id":"BI and Visualizer/Widgets/Viewing widget data","title":"Viewing widget data","description":"You can view widget data in different modes and views.","permalink":"/datagol-knowlegde-base-v1/docs/BI and Visualizer/Widgets/viewing-widget-data"},{"id":"BI and Visualizer/Widgets/Widget types","title":"Widget types","description":"DataGOL provides a diverse selection of data visualization widgets, enabling users to represent information graphically for effective analysis and interpretation across a wide range of data visualization requirements. The following types are of widgets are included in DataGOL.","permalink":"/datagol-knowlegde-base-v1/docs/BI and Visualizer/Widgets/widget-types"}],"unlisted":false}}')}}]);